    "TnaimMishpatiim": [
      {
        "key": "1",
        "value": "אנו מעוניינים במתן הרשאה למשתמש חדש, לצפייה והכנת פעולות (שיבוצעו אך ורק אחרי מתן אישור החברה באינטרנט, על פי זכויות החתימה הרלבנטיות). זהות המשתמש ייקבע על ידי החברה ובאחריותה הבלעדית."
      },
      {
        "key": "2",
        "value": "חברתנו תהיה אחראית באופן בלעדי לכל פעולה של מי שיוסמך מטעמה להשתמש בסיסמה."
      },
      {
        "key": "3",
        "value": "ידוע לנו כי לבנק אין כל יכולת פיקוח על זהות המשתמשים בסיסמה מטעמינו."
      },
      {
        "key": "4",
        "value": "אנו נהיה אחראים לכל הסיכונים הנובעים והכרוכים בשימוש במאגר המידע בדרך המבוקשת על ידנו כאמור בסעיף 1."
      },
      {
        "key": "5",
        "value": "פרט לאמור לעיל, בכל יתר תנאי ההצטרפות לא יחול כל שינוי, והם יישארו בתוקפם המלא."
      },
      {
        "key": "6",
        "value": "המשתמש שהוגדר מטעם החברה יוכל לצפות בכל המידע המוצג באתר הבנק. בנוסף יוכל לייזום עסקאות שיבוצעו אך ורק לאחר אישור החברה באינטרנט, על פי זכויות החתימה הרלבנטיות."
      },
      {
        "key": "7",
        "value": "ניתן לבטל ולערוך את המשתמש בכל עת באתר הפעולות של הבנק."
      },
      {
        "key": "8",
        "value": "ברשות הבנק נתונה הזכות לבטל את הרשאה למשתמש בהתאם לשיקול דעתו."
      }
    ]
